28→// RogerRoger implements the Agent interface using a deterministic external
29→// agent binary that creates files and fires hooks without making any API calls.
30→// Unlike built-in agents (Vogon, Claude Code, etc.), roger-roger is discovered
31→// via the external agent protocol (entire-agent-roger-roger binary in $PATH).
32→type RogerRoger struct{}
33→
34→func (r *RogerRoger) Name() string                            { return "roger-roger" }
35→func (r *RogerRoger) Binary() string                          { return "roger-roger" }
36→func (r *RogerRoger) EntireAgent() string                     { return "roger-roger" }
37→func (r *RogerRoger) PromptPattern() string                   { return `>` }
38→func (r *RogerRoger) TimeoutMultiplier() float64              { return 0.5 } // Deterministic, no API calls
39→func (r *RogerRoger) Bootstrap() error                        { return nil }
40→func (r *RogerRoger) IsTransientError(_ Output, _ error) bool { return false }
41→
42→// IsExternalAgent returns true — roger-roger is discovered via the external agent protocol.
43→func (r *RogerRoger) IsExternalAgent() bool { return true }
44→
45→func (r *RogerRoger) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
46→	// roger-roger reads prompts from stdin line by line.
47→	// An empty line causes the REPL to exit gracefully.
48→	cmd := exec.CommandContext(ctx, r.Binary())
49→	cmd.Dir = dir
50→	cmd.Stdin = strings.NewReader(prompt + "\n\n")
51→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
52→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
53→	cmd.Cancel = func() error {
54→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
55→	}
56→	cmd.WaitDelay = 5 * time.Second
57→
58→	var stdout, stderr strings.Builder
59→	cmd.Stdout = &stdout
60→	cmd.Stderr = &stderr
61→
62→	err := cmd.Run()
63→	exitCode := 0
64→	if err != nil {
65→		exitErr := &exec.ExitError{}
66→		if errors.As(err, &exitErr) {
67→			exitCode = exitErr.ExitCode()
68→		} else {
69→			exitCode = -1
70→		}
71→	}
72→
73→	return Output{
74→		Command:  "roger-roger <<< " + fmt.Sprintf("%q", prompt),
75→		Stdout:   stdout.String(),
76→		Stderr:   stderr.String(),
77→		ExitCode: exitCode,
78→	}, err
79→}
