81→func (r *RogerRoger) StartSession(_ context.Context, dir string) (Session, error) {
82→	name := fmt.Sprintf("rr-test-%d", time.Now().UnixNano())
83→	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, r.Binary())
84→	if err != nil {
85→		return nil, err
86→	}
87→
88→	// Wait for the interactive prompt.
89→	if _, err := s.WaitFor(`>`, 10*time.Second); err != nil {
90→		_ = s.Close()
91→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
92→	}
93→	s.stableAtSend = ""
94→
95→	return s, nil
96→}
